#include <bits/stdc++.h>
#include <atcoder/all>
using namespace std;
using namespace atcoder;

int main() {
	int n;
	cin>> n;

	vector<int>a(n),b(n),c(n),aa(2*n),bb(n),cc;
	for(int i=0;i<n;i++)cin>>a[i];
	for(int i=0;i<n;i++)cin>>b[i];

	for(int j=0;j<5;j++){
		for(int i=0;i<n;i++){
			aa[i]=(~a[i]>>j)&1;
			aa[n+i]=aa[i];
			bb[n-i-1]=(~b[i]>>j)&1;
		}
		cc=convolution(aa, bb);
		for(int i=0;i<n;i++){
			c[i]+=(n-cc[n+i-1])<<j;
		}
	}

	int ans=0;
	for(int i=0;i<n;i++)ans=max(ans,c[i]);
	cout<<ans<<endl;
	return 0;
}
